echo "Deleted count: ", $result->getDeletedCount(), "\n";
echo "Inserted IDs: ", implode(', ', $result->getInsertedIds()), "\n";

// Clean up
$collection->drop();
?>

--EXPECTF--
Inserted count: 2
Matched count: 1
Modified count: 1
Deleted count: 1
Inserted IDs: %s, %s
