Below is an `awk` script that performs the tasks you've described. The script expects two arguments: the first is the custom field separator, and the second is the input file. If you want to use a text stream instead of a file, you can pipe the input into the script and omit the second argument.

```awk
#!/usr/bin/awk -f

BEGIN {
    # The first argument is the custom field separator
    FS = ARGV[1];
    # Remove the first argument so it's not treated as a filename
    delete ARGV[1];
    # Define a regex pattern for a well-formed URL according to RFC 3986
    urlPattern = "^http(s)?://(([a-zA-Z0-9\\-\\.]+\\.[a-zA-Z]{2,4})|localhost)(:[0-9]+)?(/[^\\s]*)?$";
    # Start the JSON output
    print "[";
    isFirstLine = 1;
}

function isTimestamp(ts) {
    return ts ~ /^[0-9]+$/ && ts > 0;
}

function reverseString(str) {
    rev = "";
    for (i = length(str); i > 0; i--) {
        rev = rev substr(str, i, 1);
    }
    return rev;
}

function toDateTime(ts) {
    cmd = "date -d @" ts " +\"%Y-%m-%d %H:%M:%S\"";
    cmd | getline result;
    close(cmd);
    return result;
}

{
    if (NF == 3 && isTimestamp($1) && $2 ~ urlPattern) {
        if (!isFirstLine) {
            print ",";
        }
        isFirstLine = 0;
        timestamp = toDateTime($1);
        url = $2;
        reversedString = reverseString($3);
        printf "{ \"date\": \"%s\", \"url\": \"%s\", \"reversed_string\": \"%s\" }", timestamp, url, reversedString;
    }
}

END {
    print "\n]";
}
```

