### CUDA Matrix Multiplication (matrixMul.cu)

```cuda
#include <cuda_runtime.h>
#include <device_launch_parameters.h>
#include <iostream>

#define TILE_WIDTH 16 // You may want to tune this based on your GPU's specs

__global__ void matrixMulKernel(float* d_M, float* d_N, float* d_P, int width, int height) {
    __shared__ float tile_M[TILE_WIDTH][TILE_WIDTH];
    __shared__ float tile_N[TILE_WIDTH][TILE_WIDTH];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    // Calculate the row and column index of the P element to work on
    int row = by * TILE_WIDTH + ty;
    int col = bx * TILE_WIDTH + tx;

    float Pvalue = 0;

    // Loop over the M and N tiles required to compute the P element
    for (int m = 0; m < (width - 1) / TILE_WIDTH + 1; ++m) {
        // Collaborative loading of M and N tiles into shared memory
        if (m * TILE_WIDTH + tx < width && row < height)
            tile_M[ty][tx] = d_M[row * width + m * TILE_WIDTH + tx];
        else
            tile_M[ty][tx] = 0.0;

        if (m * TILE_WIDTH + ty < width && col < height)
            tile_N[ty][tx] = d_N[(m * TILE_WIDTH + ty) * height + col];
        else
            tile_N[ty][tx] = 0.0;

        __syncthreads();

        for (int k = 0; k < TILE_WIDTH; ++k) {
            Pvalue += tile_M[ty][k] * tile_N[k][tx];
        }
        __syncthreads();
    }

    if (row < height && col < width) {
        d_P[row * width + col] = Pvalue;
    }
}

void matrixMultiply(float* h_M, float* h_N, float* h_P, int width, int height) {
    // Allocate and load M, N to device memory
    float *d_M, *d_N, *d_P;
    size_t size = width * height * sizeof(float);
    cudaMalloc(&d_M, size);
    cudaMemcpy(d_M, h_M, size, cudaMemcpyHostToDevice);
    cudaMalloc(&d_N, size);
    cudaMemcpy(d_N, h_N, size, cudaMemcpyHostToDevice);
    cudaMalloc(&d_P, size);

    // Kernel launch code – we'll assume the matrices are square for simplicity
    dim3 dimBlock(TILE_WIDTH, TILE_WIDTH);
    dim3 dimGrid((width - 1) / TILE_WIDTH + 1, (height - 1) / TILE_WIDTH + 1);
    matrixMulKernel<<<dimGrid, dimBlock>>>(d_M, d_N, d_P, width, height);

    // Read P from device memory
    cudaMemcpy(h_P, d_P, size, cudaMemcpyDeviceToHost);

    // Free device memory
    cudaFree(d_M);
    cudaFree(d_N);
    cudaFree(d_P);
}

int main() {
    // Matrix dimensions
    int width = 1024; // Example size, adjust as needed
    int height = 1024; // Example size, adjust as needed

    // Allocate and initialize host memory
    float *h_M, *h_N, *h_P;
    h_M = new float[width * height];
    h_N = new float[width * height];
    h_P = new float[width * height];
    // Initialize h_M and h_N with your data

    // Perform matrix multiplication on the GPU
    matrixMultiply(h_M, h_N, h_P, width, height);

    // Cleanup
    delete[] h_M;
    delete[] h_N;
    delete[] h_P;

    return 0;
}
```

### CPU Matrix Multiplication (matrixMul.cpp)

```cpp
#include <iostream>
#include <vector>

void matrixMultiplyCPU(const std::vector<std::vector<float>>& A, const std::vector<std::vector<float>>& B, std::vector<std::vector<float>>& C) {
    int A_rows = A.size();
    int A_cols = A[0].size();
    int B_cols = B[0].size();

    for (int i = 0; i < A_rows; ++i) {
        for (int j = 0; j < B_cols; ++j) {
            float sum = 0.0f;
            for (int k = 0; k < A_cols; ++k) {
                sum += A[i][k] * B[k][j];
            }
            C[i][j] = sum;
        }
    }
}

int main() {
    // Example usage
    std::vector<std::vector<float>> A = {{1, 2}, {3, 4}};
    std::vector<std::vector<float>> B = {{5, 6}, {7, 8}};
    std::vector<std::vector<float>> C(2, std::vector<float>(2, 0));

    matrixMultiplyCPU(A, B, C);

    // Output the result
    for (const auto& row : C) {
        for (float val : row) {
            std::cout << val << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
```

